"use client";

import * as React from "react";
import { IconDefinition, PixelIconProps } from "@/lib/icons/schema";

export interface PixelIconBaseProps extends PixelIconProps {
  definition: IconDefinition;
}

export const PixelIconBase = React.forwardRef<SVGSVGElement, PixelIconBaseProps>(
  (
    {
      definition,
      size = 24,
      color = "currentColor",
      strokeWidth,
      filled = false,
      animated = false,
      animation,
      duration,
      delay,
      loop = true,
      trigger = "auto",
      className = "",
      title,
      "aria-label": ariaLabel,
      style,
      ...restProps
    },
    ref
  ) => {
    // Resolve width/height from number or string (e.g. 24, "24px", "1.5rem")
    const dimension = typeof size === "number" ? `${size}px` : size;

    const rawPaths: Array<{ d: string; fillRule?: any; clipRule?: any }> =
      (definition as any)?.geometry?.paths || (definition as any)?.paths || [];
    const rawFilled: Array<{ d: string; fillRule?: any; clipRule?: any }> | undefined =
      (definition as any)?.geometry?.filled || (definition as any)?.filled;
    const paths: Array<{ d: string; fillRule?: any; clipRule?: any }> =
      filled && rawFilled && rawFilled.length > 0 ? rawFilled : rawPaths;

    const hasAnimation = animated && Boolean(definition.animation);
    const animationClass = hasAnimation ? definition.animation?.cssClass || "" : "";

    const isMeaningful = Boolean(ariaLabel || title);

    const animationStyle: React.CSSProperties = {};
    if (hasAnimation) {
      if (duration !== undefined) {
        animationStyle.animationDuration = `${duration}ms`;
      }
      if (delay !== undefined) {
        animationStyle.animationDelay = `${delay}ms`;
      }
      if (loop === false) {
        animationStyle.animationIterationCount = "1";
      }
    }

    return (
      <svg
        ref={ref}
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        width={dimension}
        height={dimension}
        fill={color}
        className={`pixel-crisp inline-block shrink-0 select-none ${animationClass} ${className}`.trim()}
        role={isMeaningful ? "img" : undefined}
        aria-hidden={isMeaningful ? undefined : true}
        aria-label={ariaLabel}
        style={{
          color,
          shapeRendering: "crispEdges",
          ...animationStyle,
          ...style,
        }}
        {...restProps}
      >
        {title ? <title>{title}</title> : null}
        {paths.map((p, idx) => (
          <path
            key={idx}
            d={p.d}
            fillRule={p.fillRule}
            clipRule={p.clipRule}
          />
        ))}
      </svg>
    );
  }
);

PixelIconBase.displayName = "PixelIconBase";

// Backward-compatibility exports
export const PXIconBase = PixelIconBase;
export type PXIconBaseProps = PixelIconBaseProps;

export type IconCategory =
  | "Actions & Controls"
  | "Arrows & Navigation"
  | "Files & Folders"
  | "Communication"
  | "People & Social"
  | "Devices & Hardware"
  | "Development & Code"
  | "Business & Finance"
  | "Commerce"
  | "Media & Creative"
  | "Maps & Travel"
  | "Buildings & Objects"
  | "Health & Fitness"
  | "Weather & Nature"
  | "Security & Privacy"
  | "Time & Calendar"
  | "Education"
  | "AI & Emerging Tech"
  | "Brands & Technology"
  | "Miscellaneous & Symbols";

export type AnimationFamily =
  | "state"
  | "directional"
  | "attention"
  | "reveal"
  | "signal"
  | "loop";

export type AnimationType =
  | "spin"
  | "pulse"
  | "bounce"
  | "wiggle"
  | "blink"
  | "ring"
  | "shake"
  | "beat";

export type AnimationName =
  | "spin"
  | "pulse"
  | "bounce"
  | "wiggle"
  | "blink"
  | "ring"
  | "shake"
  | "beat"
  | "open"
  | "close"
  | "check"
  | "error"
  | "success"
  | "download"
  | "upload"
  | "appear"
  | "disappear"
  | "loading"
  | string;

export interface AnimationDefinition {
  family: AnimationFamily;
  type: AnimationType;
  cssClass: string;
  description: string;
  duration?: number;
  trigger?: "auto" | "hover" | "click" | "focus" | "controlled" | "always" | "mount";
}

export interface BrandDefinition {
  brand: string;
  owner: string;
  source?: string;
  guidelinesUrl?: string;
}

export interface IconPathDefinition {
  d: string;
  fillRule?: "nonzero" | "evenodd";
  clipRule?: "nonzero" | "evenodd";
}

export interface IconDefinition {
  name: string; // lowercase-kebab-case, e.g. "home", "search"
  componentName?: string; // Public framework component name, e.g. "PXIconHome"
  slug?: string; // Registry, URL and artifact identifier, e.g. "px-home"
  title: string;
  description?: string;
  category: IconCategory;
  family?: string; // Related geometric/semantic family (Section 7.19)
  tags: string[];
  aliases?: string[];
  grid: 24;
  paths: IconPathDefinition[];
  filled?: IconPathDefinition[];
  variants?: string[]; // Supported canonical variants, e.g. ["outline", "filled"]
  animation?: AnimationDefinition;
  brand?: BrandDefinition;
  platforms?: string[]; // Supported generated targets (Section 7.27)
  status?: "draft" | "experimental" | "stable" | "deprecated"; // Lifecycle state (Section 7.28)
  introduced?: string; // First PXUI release containing icon (Section 7.29)
  introducedVersion: string;
  deprecated?: boolean; // Deprecation state (Section 7.30)
  replacedBy?: string; // Migration target when deprecated
}

/**
 * PixelIconProps conforming strictly to Section 3.11.1 of the design system specification.
 */
export interface PixelIconProps extends React.SVGProps<SVGSVGElement> {
  size?: number | string;
  color?: string;
  strokeWidth?: number;
  animated?: boolean;
  animation?: AnimationName;
  duration?: number;
  delay?: number;
  loop?: boolean;
  trigger?: "auto" | "hover" | "click" | "focus" | "controlled";
  filled?: boolean;
  title?: string;
  className?: string;
  "aria-label"?: string;
}

/**
 * Backward compatibility alias for PXIconProps
 */
export type PXIconProps = PixelIconProps;
